const calls = [];

const square = new Proxy((n) => n * n, {
  apply(target, thisArg, args) {
    calls.push(args.length);
    return Reflect.apply(target, thisArg, args) + 1;
  },
});

class Tag {
  constructor(label) {
    this.label = label;
  }
}

const Loud = new Proxy(Tag, {
  construct(target, [label], newTarget) {
    return Reflect.construct(target, [label.toUpperCase()], newTarget);
  },
});

console.log(square(3), square(2, 9));
console.log(calls.join(","));
console.log(new Loud("sale").label, new Loud("x") instanceof Tag);
